var e=(e,...t)=>{if(!e)return!0;let n=e.trim().toLowerCase().split(/\s+/).filter(Boolean);if(n.length===0)return!0;let r=[],i=[];for(let e of t)if(e!=null&&e!==``){let t=String(e).toLowerCase().split(/[^\p{L}\p{N}]+/gu).filter(Boolean);for(let e of t)r.push(e),i.push(e.normalize(`NFD`).replace(/[\u0300-\u036f]/g,``))}return r.length!==0&&n.every(e=>{let t=e.replace(/[^\p{L}\p{N}]/gu,``).toLowerCase();if(!t)return!0;let n=t.normalize(`NFD`).replace(/[\u0300-\u036f]/g,``);return r.some((e,r)=>e.startsWith(t)||i[r].startsWith(n))})};export{e as t};